  {
   "name": "Auth",
   "description": "Login to obtain a Bearer token (auto-stored in {{token}}), logout to revoke, and a no-token 401 check.",
   "item": [
    {
     "name": "Login (get token)",
     "event": [
      {
       "listen": "test",
       "script": {
        "type": "text/javascript",
        "exec": [
         "pm.test('200 OK', function () { pm.response.to.have.status(200); });",
         "var b = pm.response.json();",
         "pm.collectionVariables.set('token', b.token);",
         "pm.test('token returned', function () { pm.expect(b.token).to.be.a('string').and.not.empty; });",
         "console.log('Stored token:', b.token);"
        ]
       }
      }
     ],
     "request": {
      "auth": {
       "type": "noauth"
      },
      "method": "POST",
      "header": [
       {
        "key": "Content-Type",
        "value": "application/json"
       }
      ],
      "body": {
       "mode": "raw",
       "raw": "{\n  \"username\": \"admin\",\n  \"password\": \"admin123\"\n}"
      },
      "url": {
       "raw": "{{serverUrl}}/auth/login",
       "host": [
        "{{serverUrl}}"
       ],
       "path": [
        "auth",
        "login"
       ]
      }
     }
    },
    {
